const types = yield* Database.resolve('dxn:org.dxos.operation.assistantToolkit.queryTypes');
const res = yield* Operation.invoke(types, { typenames: ['com.example.type.task'] });
yield* print(res);
const Task = yield* Database.resolve('dxn:com.example.type.task:0.1.0');
const all = yield* Database.query(Filter.type(Task)).run;
yield* print('total tasks', all.length);
for (const t of all) {
  yield* print(t.id, '|', t.status, '|', t.title);
}

const Task = yield* Database.resolve('dxn:com.example.type.task:0.1.0');
const all = yield* Database.query(Filter.type(Task)).run;
const matches = all.filter((t) => t.title.toLowerCase().includes('doc'));
for (const t of matches) {
  Obj.update(t, (task) => { task.status = 'done'; });
  yield* print('closed', t.id, t.title);
}
yield* Database.flush();
const after = yield* Database.query(Filter.type(Task)).run;
yield* print('done count', after.filter((t) => t.status === 'done').length, 'of', after.length);
